"""Second curriculum batch: coherent Python pathway and supporting track modules.

The records are authored as compact specifications, then expanded into the same
lesson/question shape consumed by the existing deterministic importer.
"""

PYTHON_MODULES = [
    ('py-setup', 'Environment and Python Workflow', 'Install Python, run scripts, and use a predictable project setup.', 1),
    ('py-control', 'Control Flow and Functions', 'Make decisions, repeat work, and compose reusable behavior.', 2),
    ('py-collections', 'Collections and Iteration', 'Model groups of values and transform them clearly.', 3),
    ('py-io', 'Modules, Files, and Data', 'Organize programs and work with persistent structured data.', 4),
    ('py-quality', 'Errors, Testing, and Design', 'Diagnose failures and build maintainable Python programs.', 5),
    ('py-advanced', 'Python Abstractions and Projects', 'Use object models, generators, decorators, and practical project patterns.', 6),
]

# slug, title, module, minutes, summary, prerequisite slugs, explanation, four facts
PYTHON_TOPICS = [
('py-installation', 'Installing Python and Choosing an Interpreter', 'py-setup', 25, 'Set up a repeatable Python interpreter and understand which executable runs your code.', [], 'A Python project is only reproducible when its interpreter and dependencies are explicit. Check the interpreter with python --version and identify the executable with a small diagnostic command. On systems with several installations, using python -m pip ties pip to the interpreter that will run the program.', [('interpreter','The interpreter executes Python source code.'),('python-m','python -m runs a module with the selected interpreter.'),('version','A version check makes runtime assumptions visible.'),('reproducibility','A repeatable setup records the interpreter and dependencies.')]),
('py-running-scripts', 'Running Scripts and the REPL', 'py-setup', 25, 'Choose between interactive exploration and repeatable script execution.', ['py-installation'], 'The REPL is useful for trying a small expression and inspecting an object, while a script records a sequence that can be rerun. A module guard keeps code from running on import when the file is used as a library. Good workflow moves a successful experiment into a named, testable function.', [('repl','The REPL evaluates expressions interactively.'),('script','A script is a saved sequence of statements.'),('main-guard','if __name__ == "__main__" runs a block only when the file is executed directly.'),('repeatability','Saved code can be rerun after inputs or implementation change.')]),
('py-lexical-syntax', 'Syntax, Indentation, and Statements', 'py-setup', 25, 'Read Python blocks, statements, comments, and syntax errors.', ['py-running-scripts'], 'Python uses indentation to delimit blocks, so consistent whitespace is part of program syntax. A syntax error prevents parsing before the program starts; it is different from a runtime exception. Keep statements simple while learning to isolate the exact line and construct that the parser rejected.', [('indentation','Indentation groups statements into a block.'),('syntax-error','A syntax error prevents the source from being parsed.'),('statement','A statement performs an action or controls execution.'),('comment','A comment documents intent for readers and is ignored by the interpreter.')]),
('py-input-output', 'Input, Output, and Conversion', 'py-setup', 30, 'Read text input, display results, and convert values deliberately.', ['py-lexical-syntax'], 'input returns text even when the user types digits, so numeric work requires an explicit conversion such as int or float. Output should state units and assumptions when a person will read it. Conversion can fail, which makes validation and a helpful error path part of a robust input boundary.', [('input','input returns a string supplied by the user.'),('conversion','int and float convert suitable text to numeric values.'),('output','print writes a human-readable representation.'),('validation','Validation checks whether input satisfies the expected contract.')]),
('py-operators', 'Operators, Precedence, and Comparisons', 'py-control', 30, 'Combine arithmetic, comparison, Boolean, and membership operators predictably.', ['py-values'], 'Expressions are evaluated according to precedence and associativity, but parentheses make important grouping explicit. Comparisons produce Booleans and can be chained in Python. Use equality to compare values and identity only for object identity tests such as checking a singleton sentinel.', [('precedence','Precedence determines which operator groups first.'),('comparison','A comparison evaluates to True or False.'),('equality','== compares values according to their equality operation.'),('identity','is tests whether two names refer to the same object.')]),
('py-branching', 'Branching and Guard Clauses', 'py-control', 30, 'Structure conditional paths and reject invalid states early.', ['py-operators'], 'An if chain should express mutually exclusive cases in a deliberate order. Guard clauses handle invalid or exceptional cases near the boundary, reducing nesting in the main path. Conditions should describe domain rules rather than rely on accidental truthiness when a precise comparison is required.', [('guard','A guard clause handles a precondition before the main path.'),('elif','Only the first true branch in an if/elif chain executes.'),('else','else is the fallback when preceding conditions are false.'),('truthiness','Objects have a Boolean context, but explicit comparisons can communicate intent better.')]),
('py-while-loops', 'While Loops and Termination', 'py-control', 30, 'Write condition-controlled loops with a visible progress argument.', ['py-branching'], 'A while loop checks its condition before each iteration. To show that it terminates, identify a value that changes toward a boundary and ensure every path updates it or exits. If no state changes, the loop may never finish; if the update skips the boundary, the condition may remain true.', [('condition','The while condition is checked before each iteration.'),('progress','A progress measure moves toward termination.'),('break','break exits the nearest loop immediately.'),('invariant','A loop invariant remains true at the relevant points of execution.')]),
('py-functions-design', 'Function Contracts and Decomposition', 'py-control', 35, 'Decompose a problem into functions with clear inputs, outputs, and side effects.', ['py-functions'], 'A function contract describes acceptable inputs, returned results, and meaningful side effects. Decomposition reduces the amount of behavior a reader must hold in mind at once. Prefer a return value for computation and isolate I/O at the boundary so the core logic is easy to test.', [('contract','A contract states what callers may provide and what they receive.'),('decomposition','Decomposition splits a large problem into focused units.'),('side-effect','A side effect changes state outside the returned value.'),('composition','Small functions can be combined by passing one result to another.')]),
('py-scope', 'Scope, LEGB, and Name Resolution', 'py-control', 35, 'Predict where Python looks for names and avoid accidental global state.', ['py-functions'], 'Python resolves an unqualified name through local, enclosing, global, and built-in scopes. A local assignment makes a name local to that function unless declared otherwise, which can produce an UnboundLocalError when read first. Pass dependencies explicitly instead of relying on mutable globals.', [('local','A local name belongs to the current function invocation.'),('enclosing','An enclosing scope belongs to an outer function.'),('global','A global name is defined at module scope.'),('closure','A closure retains access to names from an enclosing scope.')]),
('py-defaults-keywords', 'Default and Keyword Arguments', 'py-control', 30, 'Call functions safely with positional, keyword, and default arguments.', ['py-functions'], 'Arguments are matched to parameters by position or name. Defaults are evaluated when the def statement executes, not on every call, so mutable defaults can accidentally share state across invocations. Use None as a sentinel and create a fresh object inside when necessary.', [('positional','A positional argument is matched by its position.'),('keyword','A keyword argument names the parameter it supplies.'),('default','A default supplies a value when a caller omits an argument.'),('mutable-default','A mutable default object is shared across calls unless handled deliberately.')]),
('py-recursion', 'Recursion and Base Cases', 'py-control', 35, 'Break recursive problems into smaller calls with a correct stopping condition.', ['py-functions-design'], 'A recursive function calls itself on a smaller instance and must have a base case that returns without another recursive call. Each call owns local state on the call stack. Recursion can mirror a tree or divide-and-conquer structure, but iteration may be clearer when depth is large.', [('base-case','A base case stops recursive expansion.'),('recursive-case','A recursive case reduces the problem toward a base case.'),('call-stack','Each active call has its own frame and local bindings.'),('depth','Recursion depth is bounded by the number of nested active calls.')]),
('py-lists', 'Lists and Mutable Sequences', 'py-collections', 35, 'Create, index, update, and safely copy mutable list data.', ['py-values'], 'A list is an ordered mutable sequence. Indexing reads one element, slicing creates a new list, and methods such as append mutate the existing object. Assignment to a variable does not copy a list; use copy or a slice when independent top-level storage is intended.', [('list','A list stores an ordered collection and can be mutated.'),('append','append adds one object to the end of a list.'),('slice','A list slice creates a new list containing the selected positions.'),('alias','Two names alias when they reference the same object.')]),
('py-tuples', 'Tuples, Packing, and Unpacking', 'py-collections', 30, 'Use immutable tuples and unpacking for fixed-shape values.', ['py-lists'], 'Tuples are immutable sequences and are useful for records whose shape should not change. Packing collects expressions into a tuple; unpacking assigns its elements to names. Immutability prevents replacing tuple positions, although a tuple may contain a mutable object whose own state can change.', [('tuple','A tuple is an immutable sequence.'),('packing','Packing groups multiple values into one tuple.'),('unpacking','Unpacking assigns elements from an iterable to names.'),('immutability','Immutability prevents rebinding an object’s internal positions.')]),
('py-dictionaries', 'Dictionaries and Key-Value Modeling', 'py-collections', 35, 'Represent relationships with dictionaries and handle missing keys intentionally.', ['py-lists'], 'A dictionary maps hashable keys to values. Lookup by key is typically constant time but depends on hashing and implementation details. Use get when absence is expected, [] when absence is an error, and setdefault or defaultdict only when their creation semantics match the data model.', [('mapping','A mapping associates keys with values.'),('hashable','A hashable key has a stable hash and equality behavior.'),('get','get can return a fallback instead of raising for a missing key.'),('key-uniqueness','Each key occurs at most once in a dictionary.')]),
('py-sets', 'Sets and Set Algebra', 'py-collections', 30, 'Remove duplicates and express membership and set relationships clearly.', ['py-lists'], 'A set stores unique hashable elements without promising list-like positional order. Membership is usually efficient, and union, intersection, and difference express common data operations directly. Convert to a list only when an ordered result is required, and then define the ordering explicitly.', [('uniqueness','A set keeps one occurrence of each equal element.'),('membership','in tests whether an element belongs to a set.'),('intersection','Intersection contains values present in both sets.'),('difference','Difference contains values in the left set but not the right set.')]),
('py-slicing', 'Indexing, Slicing, and Extended Slices', 'py-collections', 30, 'Use start, stop, and step to select sequence regions without off-by-one errors.', ['py-lists'], 'A slice selects positions from start up to but excluding stop, moving by step. Omitted bounds use sequence-dependent defaults, and a negative step traverses backward. Slices produce a new sequence for common built-in sequences rather than a view, so later mutation has separate semantics.', [('start','The start bound is included when the slice reaches it.'),('stop','The stop bound is excluded.'),('step','step controls the stride and may be negative.'),('reverse','A negative step traverses from higher indexes toward lower indexes.')]),
('py-comprehensions', 'List, Set, and Dictionary Comprehensions', 'py-collections', 35, 'Build collections declaratively while keeping transformation and filtering readable.', ['py-lists', 'py-sets', 'py-dictionaries'], 'A comprehension maps an iterable expression into a new collection and may filter items with a condition. It is best when the transformation is short and the data flow is obvious; nested comprehensions can hide complexity. The loop variable does not leak into the surrounding scope in modern Python.', [('mapping','The expression at the front computes each output value.'),('filter','An if clause keeps only items satisfying a condition.'),('nesting','A nested comprehension represents nested iteration.'),('readability','A regular loop is preferable when a comprehension becomes difficult to scan.')]),
('py-iterables', 'Iterables, Iterators, and for Loops', 'py-collections', 35, 'Explain the protocol that lets Python iterate over sequences and custom objects.', ['py-lists'], 'An iterable can produce an iterator, while an iterator remembers progress and supplies the next item until StopIteration. A for loop requests an iterator and repeatedly calls next behind the scenes. This protocol lets code consume lists, files, generators, and custom data sources uniformly.', [('iterable','An iterable can provide an iterator.'),('iterator','An iterator produces successive values and remembers its position.'),('next','next requests one value from an iterator.'),('stop-iteration','StopIteration signals that an iterator is exhausted.')]),
('py-zip-enumerate', 'zip, enumerate, and Structured Traversal', 'py-collections', 30, 'Traverse related sequences together while preserving index and length semantics.', ['py-iterables'], 'enumerate pairs each item with a counter, while zip pairs items from multiple iterables and stops when the shortest is exhausted by default. These tools make intent visible and avoid manual index bookkeeping. If mismatched lengths are an error, validate them or use strict=True where supported.', [('enumerate','enumerate yields an index and item pair.'),('zip','zip yields tuples of corresponding items.'),('shortest','zip normally stops at the shortest input.'),('strict','Strict zipping can detect unequal lengths instead of silently truncating.')]),
('py-generator-expressions', 'Generator Expressions and Lazy Work', 'py-advanced', 35, 'Delay computation and process streams without materializing every result.', ['py-comprehensions', 'py-iterables'], 'A generator expression describes values that are produced on demand. Laziness can reduce peak memory and allow a pipeline to stop early, but values are consumed once and errors occur when iteration reaches the failing step. Materialize with list only when repeated access or a concrete collection is needed.', [('lazy','Lazy evaluation defers producing a value until it is requested.'),('single-pass','A generator is normally consumed once.'),('pipeline','Generator stages can feed one another without intermediate lists.'),('materialize','Materialization creates a concrete collection from an iterator.')]),
('py-modules', 'Modules, Imports, and Namespaces', 'py-io', 35, 'Split code into modules and import names without creating confusing side effects.', ['py-running-scripts', 'py-functions-design'], 'A module is a file with its own namespace. import module keeps the namespace visible, while from module import name binds a selected name locally. Imports execute module top-level code once per interpreter process, so library modules should avoid surprising work at import time.', [('module','A module is a Python file loaded as a namespace.'),('import','import binds a module object to a local name.'),('namespace','A namespace maps names to objects.'),('side-effect','Top-level import work is a side effect for the importer.')]),
('py-packages', 'Packages and Project Layout', 'py-io', 30, 'Organize related modules into packages with stable import paths.', ['py-modules'], 'A package groups modules under a shared import path. A clear src or package layout separates application code from tests and tooling. Stable public imports reduce coupling, while internal modules can change behind a deliberate interface.', [('package','A package is a namespace containing related modules.'),('import-path','An import path identifies a module within package structure.'),('public-api','A public API is the supported surface other code may use.'),('layout','Project layout communicates boundaries between code, tests, and configuration.')]),
('py-file-io', 'Files, Paths, and Context Managers', 'py-io', 35, 'Read and write files safely with pathlib and with statements.', ['py-modules'], 'Opening a file allocates an operating-system resource that must be closed even when an operation fails. A with statement provides deterministic cleanup. pathlib makes path composition explicit and portable; specify encoding for text and choose a mode that matches whether data is read, replaced, or appended.', [('pathlib','pathlib represents filesystem paths with an object API.'),('encoding','An encoding maps bytes to text characters.'),('context-manager','A context manager arranges setup and cleanup around a block.'),('append','Append mode writes after existing content rather than replacing it.')]),
('py-json', 'JSON Serialization and Data Boundaries', 'py-io', 35, 'Serialize compatible Python data to JSON and validate external data at the boundary.', ['py-file-io', 'py-dictionaries'], 'JSON is a text interchange format with objects, arrays, strings, numbers, booleans, and null. Serialization is not a lossless representation of every Python object, so convert domain objects to an explicit schema. Treat parsed JSON as untrusted input and validate required keys and types before use.', [('serialization','Serialization converts in-memory data into a storable or transferable form.'),('json-object','A JSON object is a collection of string keys and values.'),('schema','A schema states the expected shape and types of data.'),('validation','Boundary validation prevents malformed external data from contaminating core logic.')]),
('py-csv', 'CSV Data and Delimited Text', 'py-io', 30, 'Process tabular text while handling headers, quoting, and types deliberately.', ['py-file-io'], 'CSV is a delimiter-based text format rather than a database table with enforced types. Use the csv module so quoted delimiters and newlines are handled according to the format. Header names are text; convert numeric or date fields explicitly and report malformed rows instead of silently shifting columns.', [('delimiter','A delimiter separates fields in a row.'),('header','A header row names columns but does not enforce their types.'),('quoting','Quoting allows delimiters or newlines inside a field.'),('conversion','Parsed text must be converted to domain types intentionally.')]),
('py-exceptions', 'Exceptions and Recovery', 'py-quality', 35, 'Handle expected failures without hiding programming defects.', ['py-input-output', 'py-file-io'], 'Exceptions represent an abnormal condition that interrupts normal control flow. Catch the narrowest exception you can recover from, provide useful context, and let unexpected defects surface during development. A bare except can also catch interrupts and obscure the real failure, so avoid it in ordinary application code.', [('exception','An exception is an object describing an abnormal condition.'),('try','try marks code whose exceptions may be handled.'),('except','except selects a matching exception handler.'),('narrow-catch','A narrow catch limits recovery to failures the program understands.')]),
('py-custom-exceptions', 'Custom Exceptions and Error Messages', 'py-quality', 30, 'Design domain-specific errors that help callers recover or explain failure.', ['py-exceptions'], 'A custom exception gives a domain failure a stable type and message. Keep the original cause with raise ... from when translating a lower-level error, so debugging retains context. Error messages should identify the invalid value or operation without exposing secrets.', [('custom-error','A custom exception names a domain-specific failure.'),('cause-chain','Exception chaining preserves the lower-level cause.'),('message','An error message should identify what failed and why.'),('boundary','An API boundary translates internal failures into an appropriate public response.')]),
('py-debugging', 'Debugging with Tracebacks and Invariants', 'py-quality', 35, 'Turn a traceback and a failing example into a focused diagnosis.', ['py-exceptions', 'py-functions-design'], 'A traceback shows the call path and the line where an exception was raised; read it from the bottom upward for the immediate failure, then inspect callers for bad assumptions. A minimal reproducer removes unrelated input and state. Assertions document invariants during development but should not replace user-input validation.', [('traceback','A traceback records the active call stack at failure.'),('reproducer','A minimal reproducer isolates the smallest failing case.'),('assertion','An assertion checks a programmer assumption.'),('invariant','An invariant is a condition that should remain true at a program boundary.')]),
('py-unit-testing', 'Unit Tests and Testable Functions', 'py-quality', 35, 'Write focused tests that specify behavior and isolate defects.', ['py-functions-design', 'py-exceptions'], 'A unit test exercises a small unit with controlled inputs and checks an observable result. Arrange the inputs, act once, and assert the outcome. Test boundaries and failure behavior, not just the happy path; a test that mirrors implementation details can pass while behavior is wrong.', [('unit-test','A unit test checks a focused unit of behavior.'),('assertion','An assertion compares actual behavior with an expected condition.'),('fixture','A fixture supplies repeatable test setup or data.'),('boundary-case','A boundary case exercises an edge of the valid or invalid input domain.')]),
('py-test-doubles', 'Mocks, Fakes, and Dependency Boundaries', 'py-quality', 30, 'Control external dependencies in tests without over-specifying implementation.', ['py-unit-testing'], 'A test double replaces a dependency so a test can control inputs or observe calls. A fake provides a lightweight working implementation; a mock focuses on interactions. Keep the boundary small and prefer testing meaningful outcomes over asserting every internal call.', [('fake','A fake is a simplified working implementation.'),('mock','A mock records or verifies interactions with a dependency.'),('dependency','A dependency is another component a unit needs to perform its work.'),('seam','A seam is a place where behavior can be substituted for a test.')]),
('py-dataclasses', 'Dataclasses and Value Objects', 'py-advanced', 35, 'Represent structured records with explicit fields and useful generated behavior.', ['py-classes'], 'A dataclass declares the fields of a record and can generate an initializer and representation. It reduces boilerplate but does not decide domain invariants automatically; validate values at construction or in a factory. Frozen dataclasses communicate that the value object should not be mutated after creation.', [('dataclass','A dataclass generates common record methods from field declarations.'),('field','A field describes one named piece of record state.'),('frozen','A frozen dataclass prevents ordinary attribute reassignment.'),('invariant','A domain invariant is a rule every valid instance must satisfy.')]),
('py-classes', 'Classes, Instances, and Methods', 'py-advanced', 40, 'Model behavior with classes while keeping state and responsibilities clear.', ['py-functions-design'], 'A class defines behavior and a blueprint for instances. self refers to the instance receiving a method call; class attributes are shared unless shadowed by instance attributes. Use a class when the data and operations form a coherent concept, not merely to wrap a few unrelated functions.', [('class','A class defines attributes and methods shared by instances.'),('instance','An instance is a concrete object created from a class.'),('self','self refers to the receiving instance by convention.'),('method','A method is a function defined on a class and accessed through an instance or class.')]),
('py-inheritance-composition', 'Composition and Inheritance', 'py-advanced', 35, 'Choose composition or inheritance based on the relationship and change you expect.', ['py-classes'], 'Composition builds an object from collaborators and keeps relationships explicit. Inheritance reuses and specializes a base type, but it also couples the subclass to the base contract. Prefer composition for a has-a relationship and use inheritance when substitutability and a stable is-a abstraction are real.', [('composition','Composition gives an object other objects it delegates to.'),('inheritance','Inheritance derives a type from a base type.'),('substitutability','A subtype should honor the usable contract of its base abstraction.'),('coupling','Coupling measures how strongly one component depends on another.')]),
('py-dunder-protocols', 'Special Methods and Python Protocols', 'py-advanced', 35, 'Implement selected special methods to integrate objects with Python syntax.', ['py-classes'], 'Special methods such as __len__, __iter__, and __repr__ let an object participate in built-in protocols. Their names are looked up by Python for specific operations rather than usually called directly. Implement a protocol consistently: if equality changes, hashing and mutability considerations matter too.', [('protocol','A protocol is a behavioral contract recognized by an operation.'),('__repr__','__repr__ provides a developer-oriented representation.'),('__iter__','__iter__ supplies an iterator for iteration.'),('hashing','Hashing must remain consistent with equality for hashable objects.')]),
('py-context-managers', 'Context Managers and Resource Safety', 'py-advanced', 35, 'Create and use context managers to guarantee cleanup around a block.', ['py-file-io', 'py-classes'], 'A context manager supplies __enter__ and __exit__ behavior, or can be built with contextlib. The with statement calls cleanup even if the block raises. Returning true from __exit__ suppresses an exception, so do that only when the context deliberately handles the failure.', [('enter','__enter__ prepares a managed resource and returns the bound value.'),('exit','__exit__ performs cleanup and can inspect an exception.'),('cleanup','Cleanup releases a resource or restores state.'),('suppression','An exit method that returns true suppresses the active exception.')]),
('py-decorators', 'Decorators and Function Wrapping', 'py-advanced', 35, 'Wrap functions to add behavior while preserving a clear callable interface.', ['py-functions-design', 'py-closures'], 'A decorator is a callable that receives a function and returns a replacement or modified callable. The wrapper should preserve metadata with functools.wraps and should not unexpectedly change argument or return contracts. Decorators are useful for cross-cutting concerns such as logging, timing, and authorization.', [('decorator','A decorator transforms or registers a callable.'),('wrapper','A wrapper adds behavior around an underlying callable.'),('wraps','functools.wraps copies useful metadata to a wrapper.'),('cross-cutting','A cross-cutting concern affects many otherwise separate functions.')]),
('py-closures', 'Closures and Factory Functions', 'py-advanced', 35, 'Use nested functions that retain enclosing state without exposing mutable globals.', ['py-scope', 'py-functions-design'], 'A closure is a function together with bindings from its enclosing scope. The enclosed name is read through a cell after the outer function returns. Use nonlocal only when the closure intentionally updates that state; otherwise pass values explicitly for simpler reasoning.', [('closure','A closure retains access to enclosing-scope bindings.'),('free-variable','A free variable is resolved outside the current function local scope.'),('nonlocal','nonlocal permits rebinding a name in an enclosing function scope.'),('factory','A factory function creates configured objects or callables.')]),
('py-async-basics', 'Async Functions and Await', 'py-advanced', 40, 'Understand cooperative concurrency and avoid blocking an event loop.', ['py-functions-design'], 'An async function returns a coroutine object until awaited or scheduled. await yields control while an asynchronous operation is pending; it does not make CPU-bound work parallel. Use async APIs for I/O and keep blocking calls out of the event loop or move them to an appropriate worker.', [('coroutine','A coroutine represents asynchronous computation that can be resumed.'),('await','await suspends the current coroutine until an awaitable completes.'),('event-loop','An event loop schedules cooperative asynchronous tasks.'),('blocking','A blocking call prevents other event-loop tasks from running.')]),
('py-stdlib', 'The Standard Library by Task', 'py-io', 35, 'Select reliable standard-library tools for paths, dates, collections, and command-line interfaces.', ['py-modules', 'py-dictionaries'], 'The standard library offers maintained building blocks such as pathlib, datetime, collections, argparse, and logging. Choosing a focused module is safer than reimplementing common behavior. Read documentation for timezone, ordering, and error semantics rather than relying on a name that sounds familiar.', [('stdlib','The standard library ships with Python.'),('datetime','datetime represents dates and times but requires timezone care.'),('logging','logging records diagnostic events with levels and handlers.'),('argparse','argparse parses structured command-line arguments.')]),
('py-virtualenv', 'Virtual Environments and Dependencies', 'py-setup', 30, 'Isolate project dependencies and record them for another developer or deployment.', ['py-installation', 'py-packages'], 'A virtual environment gives a project an isolated site-packages directory while using the selected Python runtime. Install dependencies inside the environment and record exact or bounded versions in a requirements or project metadata file. Never assume a package installed globally is available in deployment.', [('venv','venv creates an isolated environment for project packages.'),('dependency','A dependency is an external package required by the project.'),('lock','A lock records resolved dependency versions for repeatability.'),('activation','Activation changes shell lookup convenience but is not the isolation mechanism itself.')]),
('py-type-hints', 'Type Hints and Static Reasoning', 'py-quality', 35, 'Use annotations to communicate expected shapes and catch mismatches before runtime.', ['py-functions-design', 'py-dictionaries'], 'Type hints document the intended types of values and let static tools find many mismatches before execution. They do not automatically validate runtime input. Prefer precise containers and return types, and update annotations when the contract changes.', [('annotation','An annotation records an intended type or metadata for a name.'),('static-check','A static checker analyzes code without executing the main path.'),('optional','Optional indicates a value may be absent, commonly represented by None.'),('protocol','A typing protocol describes required behavior rather than concrete inheritance.')]),
('py-cli-project', 'Building a Small Command-Line Project', 'py-advanced', 45, 'Combine parsing, domain functions, persistence, and tests into a small maintainable CLI.', ['py-argparse', 'py-json', 'py-unit-testing'], 'A useful CLI separates argument parsing, domain logic, and I/O. Parse user intent at the boundary, pass typed values into pure functions, and serialize results through one adapter. A small end-to-end project demonstrates how the earlier concepts cooperate and exposes seams for tests.', [('boundary','The CLI boundary translates text arguments into domain values.'),('pure-function','A pure function depends only on arguments and has no observable side effects.'),('adapter','An adapter translates between an external format and a domain model.'),('integration','An integration test checks that multiple components work together.')]),
('py-performance', 'Profiling and Practical Performance', 'py-quality', 35, 'Measure a bottleneck before choosing a data structure or optimization.', ['py-big-o', 'py-unit-testing'], 'Performance work starts with a representative measurement, not a guess. Big-O describes scaling while profiling identifies actual hot paths and constant costs. Preserve behavior with tests, optimize the measured bottleneck, and compare before and after under the same workload.', [('profile','Profiling measures where execution spends time.'),('benchmark','A benchmark compares performance under a defined workload.'),('bottleneck','A bottleneck limits total throughput or responsiveness.'),('regression','A performance regression makes a workload slower than its baseline.')]),
('py-project-capstone', 'Python Project: From Specification to Release', 'py-advanced', 50, 'Plan, implement, test, document, and package a small Python application.', ['py-cli-project', 'py-virtualenv', 'py-type-hints'], 'A release-ready project begins with a narrow specification and acceptance examples. Organize modules around responsibilities, validate input at boundaries, test important behavior, document setup, and make the command reproducible. A final review checks correctness, error handling, maintainability, and user-facing clarity rather than only whether the happy path works.', [('specification','A specification states behavior and acceptance conditions.'),('release','A release is a versioned deliverable that others can install or run.'),('documentation','Documentation explains setup, usage, and important design choices.'),('acceptance-test','An acceptance test verifies behavior from the user or system boundary.')]),
('py-argparse', 'Command-Line Arguments and Exit Codes', 'py-io', 30, 'Turn command-line text into validated options and useful process outcomes.', ['py-input-output', 'py-modules'], 'A command-line interface is an input boundary: parse text into typed values, reject invalid combinations with a useful message, and return an exit status that automation can interpret. Keep parsing separate from the domain operation so the operation can be tested without constructing a process.', [('argument-parser','An argument parser maps command-line tokens to named values.'),('option','An option is a named command-line setting.'),('exit-code','An exit code communicates success or failure to the calling process.'),('subcommand','A subcommand selects a related operation within one CLI.')]),
('py-big-o', 'Python Algorithm Complexity', 'py-quality', 35, 'Estimate how Python operations scale and choose structures with evidence.', ['py-lists', 'py-dictionaries'], 'Complexity analysis describes how work or memory grows with input size. A list membership scan is linear, while dictionary membership is typically constant time under normal hashing assumptions. Complexity is a model rather than a benchmark, so confirm important choices with representative measurements.', [('linear','Linear work grows proportionally with input size.'),('constant','Constant-time work does not grow with input size in the model.'),('hash-lookup','A hash lookup is typically constant time on average.'),('tradeoff','A faster lookup structure may use more memory or impose update costs.')]),
('py-pattern-matching', 'Structural Pattern Matching', 'py-control', 30, 'Use match and case to make multi-shape data decisions explicit.', ['py-branching', 'py-dictionaries'], 'Structural pattern matching compares a value with patterns and can bind parts of a matching structure. It is useful when the cases are defined by shape, not merely a long list of unrelated conditions. Include a deliberate fallback and keep guards readable.', [('pattern','A pattern describes a shape or value that may match.'),('case','A case contains one pattern branch of a match statement.'),('guard','A guard adds a Boolean condition to an otherwise matching case.'),('fallback','A fallback handles values not covered by earlier cases.')]),
]

