def _questions(slug, title, objectives, facts):
    """Create varied, deterministic questions from authored facts."""
    items = []
    templates = [
        ('concept_check', f'Which statement best explains {facts[0][0].replace("-", " ")} in {title}?'),
        ('trace', f'A learner is reasoning about {facts[1][0].replace("-", " ")}. Which conclusion follows?'),
        ('application', f'Which design choice correctly applies {facts[2][0].replace("-", " ")} in a small project?'),
        ('debugging', f'A learner made a mistake involving {facts[3][0].replace("-", " ")}. What is the best correction?'),
        ('transfer', f'Which explanation would transfer the idea from {title} to a new example?'),
        ('recall', f'What is the most precise meaning of {facts[0][0].replace("-", " ")} here?'),
        ('decision', f'Which choice is safest when applying the rules of {title}?'),
        ('explanation', f'Why does the stated approach to {facts[1][0].replace("-", " ")} work?'),
    ]
    for i, (kind, prompt) in enumerate(templates):
        fact = facts[i % 4]
        distractors = [facts[(i + j) % 4][1] for j in (1, 2, 3)]
        choices = [fact[1], *distractors]
        items.append({'prompt': prompt, 'choices': choices, 'correct': 0, 'difficulty': round(.25 + .06 * (i % 5), 2), 'type': kind,
                      'explanation': f'The key rule is: {fact[1]} This is the relevant reasoning for the objective “{objectives[i % len(objectives)]}”.',
                      'learning_objective': objectives[i % len(objectives)],
                      'distractor_explanations': [{'choice': choice, 'feedback': f'This describes {facts[(i+j)%4][0].replace("-", " ")}, not the rule tested here.'} for j, choice in enumerate(distractors, 1)],
                      'scoring_criteria': {'mode': 'exact_choice', 'points': 1}, 'provenance': 'ORBIT authored curriculum batch 2', 'review_status': 'approved'})
    return items


def _topic(spec):
    slug, title, module, minutes, summary, prerequisites, explanation, facts = spec
    objectives = [f'Explain the core rules of {title.lower()}.', f'Apply those rules to a small, concrete example.', 'Diagnose a common misuse and justify a correction.']
    return {'slug': slug, 'title': title, 'module_id': module, 'minutes': minutes, 'summary': summary,
            'objectives': objectives, 'prerequisites': prerequisites, 'explanation': explanation,
            'terminology': [{'term': k.replace('-', ' '), 'definition': v} for k, v in facts],
            'worked_examples': [{'title': f'Reason through {title.lower()}', 'steps': [f[1] for f in facts[:3]], 'takeaway': facts[3][1]}],
            'exercises': [{'prompt': f'Create a small example that demonstrates {facts[i][0].replace("-", " ")}.', 'success_criteria': f'Name the rule and explain why the result follows from it.'} for i in range(2)],
            'misconceptions': [{'claim': f'Misconception: {facts[i][1]}', 'correction': f'Check the more precise rule: {facts[(i+1)%4][1]}'} for i in range(2)],
            'mastery_criteria': [f'Explain the main ideas in {title.lower()} without copying a definition.', 'Apply the rules to an unfamiliar example and justify the result.', 'Identify a likely failure and propose a test or correction.'],
            'questions': _questions(slug, title, objectives, facts), 'review_status': 'approved', 'provenance': 'ORBIT authored curriculum batch 2', 'version': 2}


def extend_library(data):
    modules = list(data['modules'])
    topics = list(data['topics'])
    existing_modules = {m['id'] for m in modules}
    existing_topics = {t['slug'] for t in topics}
    for module_id, title, description, order in PYTHON_MODULES:
        if module_id not in existing_modules:
            modules.append({'id': module_id, 'track_id': 'python', 'title': title, 'description': description, 'sort_order': order})
    for spec in PYTHON_TOPICS:
        if spec[0] not in existing_topics:
            topics.append(_topic(spec))
    for module_id, title, track_id, description, prerequisites, explanation, facts in SUPPORTING:
        if module_id not in existing_modules:
            modules.append({'id': module_id, 'track_id': track_id, 'title': title, 'description': description, 'sort_order': 2})
        slug = module_id + '-overview'
        if slug not in existing_topics:
            topics.append(_topic((slug, title, module_id, 35, description, prerequisites, explanation, facts)))
    data['modules'] = modules
    data['topics'] = topics
    return data
